http {
    log_format timed '$remote_addr - $remote_user [$time_local] "$request" $status $body_bytes_sent "$http_referer" rt=$request_time urt=$upstream_response_time';
    access_log /var/log/nginx/access.log timed;
    server {
        listen 80;
        server_name www.example.com;
        root /var/www/site;
    }
}

http {
    log_format json escape=json '{"time":"$time_iso8601","remote_addr":"$remote_addr","method":"$request_method","uri":"$uri","status":$status,"bytes":$body_bytes_sent,"request_time":$request_time}';
    access_log /var/log/nginx/api.json.log json;
    server {
        listen 80;
        server_name api.example.com;
        location / {
            proxy_pass http://127.0.0.1:8080;
            proxy_set_header Host $host;
        }
    }
}

http {
    access_log /var/log/nginx/access.log main buffer=32k flush=5s;
    server {
        listen 80;
        server_name www.example.com;
        root /var/www/site;
    }
}

http {
    access_log syslog:server=127.0.0.1:5140,facility=local7,tag=web01,severity=info main;
    server {
        listen 80;
        server_name www.example.com;
        root /var/www/site;
    }
}

map $status $log_404 {
    404 1;
    default 0;
}
http {
    access_log /var/log/nginx/docs-404.log main if=$log_404;
    server {
        listen 80;
        server_name docs.example.com;
        root /var/www/docs;
        location / {
            try_files $uri $uri/ =404;
        }
    }
}

location /assets/ {
    root /var/www/site;
    access_log off;
    try_files $uri =404;
}

server {
    listen 80;
    server_name crm.legacy.example;
    root /var/www/crm;
    error_log /var/log/nginx/crm-error.log warn;
    location / {
        try_files $uri $uri/ =404;
    }
}

http {
    set_real_ip_from 10.0.0.0/24;
    real_ip_header X-Forwarded-For;
    real_ip_recursive on;
    access_log /var/log/nginx/access.log main;
    server {
        listen 80;
        server_name www.example.com;
        root /var/www/site;
    }
}

http {
    log_format upstream '$remote_addr [$time_local] "$request" status=$status upstream_time=$upstream_response_time connect=$upstream_connect_time';
    access_log /var/log/nginx/orders.log upstream;
    server {
        listen 80;
        server_name orders.example.com;
        location / {
            proxy_pass http://127.0.0.1:8080;
            proxy_set_header Host $host;
        }
    }
}

location /api/ {
    proxy_pass http://127.0.0.1:8080;
    proxy_set_header Host $host;
    error_log /var/log/nginx/api-error.log error;
}

http {
    access_log off;
    server {
        listen 80;
        server_name www.example.com;
        access_log /var/log/nginx/main.log combined;
        root /var/www/site;
        location / {
            try_files $uri $uri/ =404;
        }
    }
}

http {
    log_format trace '$remote_addr [$time_local] rid=$http_x_request_id "$request" $status $request_time';
    access_log /var/log/nginx/trace.log trace;
    server {
        listen 80;
        server_name www.example.com;
        root /var/www/site;
        location / {
            try_files $uri $uri/ =404;
        }
    }
}

map $status $log_5xx {
    ~^5 1;
    default 0;
}
http {
    access_log /var/log/nginx/5xx.log main if=$log_5xx;
    server {
        listen 80;
        server_name shop.example.com;
        root /var/www/shop;
        location / {
            try_files $uri $uri/ =404;
        }
    }
}

map $request_uri $loggable {
    default 1;
    ~^/healthz 0;
}
http {
    access_log /var/log/nginx/access.log main if=$loggable;
    server {
        listen 80;
        server_name app.example.com;
        root /var/www/app;
        location / {
            try_files $uri $uri/ =404;
        }
    }
}

http {
    error_log /var/log/nginx/error.log notice;
    server {
        listen 80;
        server_name www.example.com;
        root /var/www/site;
        location / {
            try_files $uri $uri/ =404;
        }
    }
}

http {
    error_log syslog:server=unix:/dev/log warn;
    server {
        listen 80;
        server_name www.example.com;
        root /var/www/site;
        location / {
            try_files $uri $uri/ =404;
        }
    }
}

http {
    log_format cache '$remote_addr [$time_local] "$request" status=$status cache=$upstream_cache_status';
    access_log /var/log/nginx/catalog-cache.log cache;
    server {
        listen 80;
        server_name catalog.example.com;
        location / {
