        }
    }
}

http {
    log_format referers '$time_local host=$host referrer="$http_referer" target="$request_uri" status=$status';
    access_log /var/log/nginx/referrers.log referers;
    server {
        listen 80;
        server_name campaign.example.com;
        root /var/www/campaign;
        location / {
            try_files $uri $uri/ =404;
        }
    }
}

server {
    listen 80;
    server_name www.popular.example;
    root /var/www/popular;
    access_log /var/log/nginx/popular.log main buffer=64k flush=5s;
    location / {
        try_files $uri $uri/ =404;
    }
}

http {
    error_log /var/log/nginx/error.log warn;
    server {
        listen 80;
        server_name search.example.com;
        error_log /var/log/nginx/search-error.log info;
        location / {
